import{_ as t,o as e,c as r,a0 as o}from"./chunks/framework.Caz7a20Z.js";const _=JSON.parse('{"title":"摸鱼的一天，顺便薅了波羊毛","description":"今天没怎么学习，但用腾讯 CNS 里的免费模型薅了羊毛，完善了自己此前的物种分布模型智能体，还做了个提取渔业信息的智能体，指使 AI 干活的感觉真不错。","frontmatter":{"title":"摸鱼的一天，顺便薅了波羊毛","date":"2026-08-23T00:00:00.000Z","tags":["日记"],"description":"今天没怎么学习，但用腾讯 CNS 里的免费模型薅了羊毛，完善了自己此前的物种分布模型智能体，还做了个提取渔业信息的智能体，指使 AI 干活的感觉真不错。"},"headers":[],"relativePath":"posts/diary-20260823.md","filePath":"posts/diary-20260823.md","lastUpdated":null}'),s={name:"posts/diary-20260823.md"};function n(i,a,d,l,p,c){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="摸鱼的一天-顺便薅了波羊毛" tabindex="-1">摸鱼的一天，顺便薅了波羊毛 <a class="header-anchor" href="#摸鱼的一天-顺便薅了波羊毛" aria-label="Permalink to &quot;摸鱼的一天，顺便薅了波羊毛&quot;">​</a></h1><p>今天坦白讲——没怎么学习嘿嘿。</p><p>但也不算白过。起因是发现了腾讯 <strong>CNS（Cloud Native？）里的免费模型</strong>，这羊毛不薅白不薅，太香了。免费额度能跑不少东西，正好拿来折腾我之前攒的几个智能体。</p><h2 id="完善物种分布模型智能体" tabindex="-1">完善物种分布模型智能体 <a class="header-anchor" href="#完善物种分布模型智能体" aria-label="Permalink to &quot;完善物种分布模型智能体&quot;">​</a></h2><p>之前写的那个<strong>物种分布模型智能体</strong>，一直有些地方没打磨好：输入的数据格式杂、跑出来的结果解释得也不够清楚。今天借着免费模型的算力，把它的流程理顺了不少——数据预处理更稳、输出也更像&quot;能直接用&quot;的样子了。</p><h2 id="顺手做了个渔业信息提取智能体" tabindex="-1">顺手做了个渔业信息提取智能体 <a class="header-anchor" href="#顺手做了个渔业信息提取智能体" aria-label="Permalink to &quot;顺手做了个渔业信息提取智能体&quot;">​</a></h2><p>还新搞了一个<strong>提取渔业信息的智能体</strong>：把一堆零散的文本、报告丢进去，让它把关键字段（渔区、物种、时间、数量……）规规矩矩抽出来。以前这种活儿得自己吭哧吭哧翻，现在一句话甩过去就出结果。</p><h2 id="指使-ai-干活-真香" tabindex="-1">指使 AI 干活，真香 <a class="header-anchor" href="#指使-ai-干活-真香" aria-label="Permalink to &quot;指使 AI 干活，真香&quot;">​</a></h2><p>说真的，能来<strong>指使 AI 干活</strong>这种感觉，挺上头的哈哈哈哈哈。</p><p>把任务拆清楚、扔给模型、等它吐结果、再挑挑拣拣——高效又省心。一边折腾一边忍不住想：<strong>这感觉自己像一个黑心资本家</strong>，坐那儿动动嘴就把活儿都分出去了，还不用发工资。</p><p>不过话说回来，能这么玩的前提，是得先把自己想要什么想明白。工具再好，也得有人把方向定住。今天就到这儿，摸鱼快乐，但明天还是得把正事儿拾起来。</p>',11)])])}const u=t(s,[["render",n]]);export{_ as __pageData,u as default};
